void HpaeGainNode::RebuildTraceName()
{
    auto rate = "rate[" + std::to_string(GetSampleRate()) + "]_";
    auto ch = "ch[" + std::to_string(GetChannelCount()) + "]_";
    auto len = "len[" + std::to_string(GetFrameLen()) + "]";
    traceName_ = "[" + std::to_string(GetSessionId()) + "]HpaeGainNode::SignalProcess " + rate + ch + len;
}

HpaePcmBuffer *HpaeGainNode::SignalProcess(const std::vector<HpaePcmBuffer *> &inputs)
{
    if (inputs.empty()) {
        AUDIO_WARNING_LOG("inputs size is empty, SessionId:%{public}d", GetSessionId());
        return nullptr;
    }
    Trace trace(traceName_);

    virtual std::string GetTraceInfo()
    {
        if (traceInfo_.empty()) {
            auto rate = "rate[" + std::to_string(nodeInfo_.samplingRate) + "]_";
            auto ch = "ch[" + std::to_string(static_cast<int32_t>(nodeInfo_.channels)) + "]_";
            auto len = "len[" + std::to_string(nodeInfo_.frameLen) + "]_";
            auto bit = "bit[" + std::to_string(static_cast<int32_t>(nodeInfo_.format)) + "]";
            traceInfo_ = rate + ch + len + bit;
        }
        return traceInfo_;
    }

protected:
    // Derived nodes rebuild their cached trace name members here, right after node info changed.
    virtual void OnTraceInfoChanged() {}

    // Clears cached trace info and notifies derived nodes; called on every node info change
    void RefreshTraceInfo()
    {
        traceInfo_.clear();
        OnTraceInfoChanged();
    }

